"""
    Starting from the given public_key, this function applies the transformation
    for loops times and returns the value
    """
def find_encryption(public_key: Any, loops: Any) -> object {
    value = 1;
    for _ in range(loops) {
        value *= public_key;
        value = value % 20201227;
    }
    return value;
}

"""Inverts age_to_eye_diameter

    Args:
         D_eye (float): Diameter of Eyepiece (mm); default is 7 mm
    Returns:
         age (float): approximate age
    """
def eye_to_age(D_eye: Any) -> object {
    if (D_eye > 7.25) {
        age = 15;
    } elif ((D_eye <= 7.25) and (D_eye > 6.75)) {
        age = 25;
    } elif ((D_eye <= 6.75) and (D_eye > 6.25)) {
        age = 33;
